# frozen_string_literal: true

require "json"

module WeatherCanadaMCP
  module Sources
    module ECCC
      # The weather.gc.ca page of a marine forecast area. The OGC API names the areas but not their pages, whose address
      # needs a map and a site number; the numbers are generated by bin/generate-marine-sites.
      module MarineSites
        # English area name => [map id, site id]
        SITES = JSON.parse(File.read(File.join(__dir__, "marine_sites.json"))).freeze
        PAGES = { "en" => "https://weather.gc.ca/marine/forecast_e.html", "fr" => "https://meteo.gc.ca/marine/forecast_f.html" }.freeze

        module_function

        # The page of the area (or part of an area, "Bowie - southern half") with this English name, or nil when unknown.
        def url(name, lang)
          map_id, site_id = SITES[name.to_s]
          "#{PAGES.fetch(lang, PAGES.fetch("en"))}?mapID=#{map_id}&siteID=#{site_id}" if map_id
        end
      end
    end
  end
end
